 t.sourceReferences=t.sourceReferences||[];t.sourceReferences.push({pdf:'2.pdf',pdfPage:29,printedPage:'58'});
 t.sourcePages=t.sourcePages||[];t.sourcePages.push({pdf:'2.pdf',pdfPage:29,printedPage:'58',title:'Isomerism and general characteristics of organic compounds',text:'Different arrangements of atoms can give compounds with the same molecular formula but different structures and properties; ethanol and dimethyl ether both have formula C2H6O. These structural isomers differ in atom arrangement. Carbon atoms form strong covalent bonds because of their small size, including bonds to one another and to H, O, N, S and halogens. General characteristics: organic compounds are mainly carbon and hydrogen (sometimes O, N, S, P or halogens); mostly covalent and often non-polar, so many do not ionize in water; generally soluble in non-polar solvents and less soluble in water; and often have low melting/boiling points because intermolecular forces are weak.'});
