(function(){
 const c=DATA.chem10Chapters&&DATA.chem10Chapters.find(x=>x.num===12);if(!c||c.__chemPdf3Pages21to24)return;c.__chemPdf3Pages21to24=true;const a=c.topics.find(x=>x.num==='12.1')||c.topics[0],b=c.topics.find(x=>x.num==='12.2')||c.topics[0];
 const add=(t,p,printed,title,text)=>{t.sourceReferences=t.sourceReferences||[];t.sourceReferences.push({pdf:'3.pdf',pdfPage:p,printedPage:printed});t.sourcePages=t.sourcePages||[];t.sourcePages.push({pdf:'3.pdf',pdfPage:p,printedPage:printed,title,text});};
 add(a,21,'80','IUPAC naming: repeated and alphabetized substituents','If the same substituent occurs repeatedly, give each position and use di-, tri-, tetra- prefixes; separate position numbers with commas. If substituents differ, list them alphabetically, e.g. ethyl before methyl. For equal-length parent chains, select the chain with the greater number of substituents. If first substituents are equally distant from either end, number from the end giving the next substituent the lower locant. Examples include 2,2-dimethylhexane, 2,2,4-trimethylhexane, 3-ethyl-4-methylhexane and 3-ethyl-2,4,5-trimethyloctane.');
 add(b,22,'81','Preparation of alkanes by addition and hydrogenation','Alkanes/cycloalkanes can be prepared by addition reactions from alkenes/alkynes or by reduction of alkyl halides. Addition places atoms on a molecule with a multiple bond. Hydrogenation adds H2 to alkenes/alkynes to form saturated alkanes; nickel catalyst at 250–300°C or platinum at room temperature is stated. Ethene + H2 → ethane. Ethyne is hydrogenated stepwise to ethene and then ethane.');
 add(b,23,'82','Reduction of alkyl halides and physical properties of alkanes','Reduction adds nascent hydrogen and replaces halogen with hydrogen, using Zn/HCl in the source: R−X + 2[H] → R−H + H−X; methyl iodide gives methane and HI, ethyl bromide gives ethane and HBr. Physical properties listed: first four alkanes are gases, next thirteen colourless liquids, higher members solids; non-polar and insoluble in water but soluble in non-polar solvents; low melting/boiling points that rise with molecular size; density rises with size; viscosity rises; flammability decreases as the carbon fraction increases.');
 add(b,24,'83','Alkane halogenation as a substitution reaction','Alkanes have strong C−C and C−H bonds and are comparatively unreactive; halogenation substitutes H with a halogen, commonly chlorine or bromine, under ultraviolet light. Methane + chlorine gives methyl chloride and HCl. In excess chlorine, successive substitutions produce dichloromethane, chloroform (trichloromethane) and tetrachloromethane. A substitution reaction replaces an atom/group (such as H or OH) with another group.');
 a.summary.en+=' IUPAC alkane naming uses di-/tri- for repeated branches, alphabetical ordering for different substituents, the most-branched parent for equal-length chains and lowest possible locants. Examples and tie-breaking rules are retained from the source.';
 a.summary.ur+=' IUPAC میں بار بار آنے والی شاخوں کے لیے di-/tri-، مختلف شاخوں کے لیے alphabetical ترتیب، برابر parent chains میں زیادہ شاخوں والی زنجیر، اور ممکنہ کم locants منتخب ہوتے ہیں۔ مثالیں اور برابر صورتوں کے قواعد اصل متن کے مطابق درج ہیں۔';
 a.summary.ps+=' په IUPAC نوم‌اېښودنه کې د تکراري څانګو لپاره di-/tri-، د بېلابېلو څانګو لپاره الفبایي ترتیب، د برابر parent chain لپاره ډېره څانګه‌لرونکې ځنځیر، او تر ټولو ټیټ ممکن locants ټاکل کېږي. بېلګې او د برابر حالت قواعد د سرچینې له مخې ثبت دي.';
 b.summary.en+=' Alkanes are prepared by hydrogenating alkenes/alkynes or reducing alkyl halides. The source gives Ni/heat and Pt/room-temperature hydrogenation conditions, Zn/HCl reductions, and physical trends across the homologous series. UV-light halogenation substitutes hydrogen stepwise to form haloalkanes.';
 b.summary.ur+=' Alkenes/alkynes کی hydrogenation یا alkyl halides کی reduction سے alkanes بنتے ہیں۔ کتاب Ni/حرارت اور Pt/کمرۂ درجہ حرارت، Zn/HCl reduction، homologous series کی طبعی تبدیلیاں، اور UV روشنی میں مرحلہ وار hydrogen کی جگہ halogen آنے کا عمل دیتی ہے۔';
 b.summary.ps+=' Alkenes/alkynes په hydrogenation یا د alkyl halides په reduction alkanes جوړوي. کتاب د Ni/تودوخې او Pt/د خونې تودوخې، Zn/HCl reduction، په homologous series کې فزیکي بدلونونه، او د UV رڼا لاندې د هایدروجن پر ځای د halogen پړاویز بدلون ښيي.';
})();
