 const fire=pet.subtopics.find(x=>x.num==='16.4.6')||{num:'16.4.6',name:'Fire Classes and Extinguishers',desc:''};fire.name='Fire Classes and Extinguishers';fire.desc='The textbook classifies fires: A—ordinary combustibles such as wood, rubber, cloth, paper and plastics; B—flammable liquids/gases such as petrol, oil paints, liquefied gas and diesel; C—electrical equipment/wiring; D—metals such as magnesium, titanium and sodium. The STS box describes water for suitable Class A fires, foam/powder/nitrogen-pressurized agents for some B fires, non-conducting agents for C fires, specialized units for D fires, and multipurpose dry chemical for A/B/C.';if(!pet.subtopics.some(x=>x.num==='16.4.6'))pet.subtopics.push(fire);
