 const a=u.activities&&u.activities.find(x=>x.num==='Activity 10.1');if(a){a.name='Reaction of Lemon Juice (acid) with Baking Soda';a.materials=['A balloon','A soft drink bottle','Lemon juice','Baking soda'];a.steps=['Before you start, stretch out the balloon to make it as easy as possible to inflate.','Pour the lemon juice into the soft drink bottle.','Add the baking soda into the balloon.','Put the balloon over the mouth of the bottle and observe what happened. Write down your own observation and the reaction.'];a.procedure=a.steps.map((x,i)=>`${i+1}. ${x}`).join('\n');a.sourceReference={pdf:'Doc1.pdf',pdfPage:26,printedPage:'24'};}
 if(s){s.desc=s.desc.replace('in 1887','in 1884');s.desc='**Properties of Acids:** The word acid is derived from the Latin word “acidus”, which means sour. Acids have sour taste. They turn blue litmus paper red and change the colour of acid-base indicators. Aqueous solutions of acids conduct electric current. Strong acids are very corrosive: they destroy fabric and cause burns on the skin.\n\n**Bases and Alkalis:** A base is any metal oxide or hydroxide that reacts with an acid to produce salt and water. A water-soluble base is called an alkali. In aqueous solution it produces hydroxide ions (OH−). All alkalis are bases but all bases are not alkalis. Bases have bitter taste and feel soapy. They turn red litmus paper blue and change acid-base indicator colours. Strong bases are corrosive and conduct electricity when dissolved in water.\n\n**Arrhenius Concept:** Svante Arrhenius, a Swedish chemist, explained that aqueous solutions of acids and bases conduct electric current by producing ions. According to the Arrhenius concept (1884), an acid is a chemical substance that dissociates in aqueous solution to give hydrogen ions (H+): HA(aq) ⇌ H+(aq) + A−(aq). Examples named in the text are HCl, H2SO4, HNO3, CH3COOH and HCN. An Arrhenius base dissociates in aqueous solution to give hydroxide ions (OH−). Some bases dissociate to release OH−; other bases react with water to remove a hydrogen ion, leaving hydroxide ions in solution: BOH(aq) ⇌ B+(aq) + OH−(aq). Examples are NaOH, KOH, NH4OH, Mg(OH)2, Ca(OH)2 and Al(OH)3.\n\n**Limitations:** The Arrhenius concept is limited to aqueous medium and does not explain acidity or basicity in non-aqueous media. It limits acids to H+ and bases to OH−, so it cannot explain the acidic nature of CO2 or the basic nature of NH3.\n\n**Summary:** Acids give H+ in water; bases give OH− in water.';s.sourceReviewNote='Printed date 1884 and all statements above follow Doc1.pdf pp.24–25; the adjacent acid and base ionization tables are stored as semantic table records.';}
 const v=t&&t.sourceFigures;if(v&&!v.some(x=>x.id==='chem10-doc1-fig10-4-alkali-subset'))v.push({id:'chem10-doc1-fig10-4-alkali-subset',title:'Fig. 10.4 Relationship between bases and alkalis',svg:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 180" role="img" aria-labelledby="alkali-title"><title id="alkali-title">All alkalis are bases, but not all bases are alkalis</title><circle cx="120" cy="92" r="78" fill="#fee2e2" stroke="#dc2626" stroke-width="4"/><circle cx="120" cy="92" r="46" fill="#ffedd5" stroke="#f97316" stroke-width="3"/><text x="120" y="98" text-anchor="middle" font-size="17">Alkalis</text><text x="120" y="166" text-anchor="middle" font-size="17">Bases</text></svg>'});
